export const BUBBLE_SIZE=48,BUBBLE_EDGE_INSET=12,BUBBLE_TOP_INSET=96,BUBBLE_GAP=10,BUBBLE_DRAG_SLOP=6;export function isBubbleable(e){return!!(e&&e.id&&e.appId&&e.canBubble)}export function isSuppressedFromShade(e,t){return!!(e&&e.id&&t&&t.has(e.id))}export function clampBubbleY(e,t,n=48,r=96,u=12){const B=r,a=Math.max(B,t-n-u);return Math.min(a,Math.max(B,e))}export function bubbleSlotY(e,t,n=48,r=10,u=96){return clampBubbleY(u+e*(n+r),t,n,u)}export function isDragMovement(e,t,n=6){return Math.hypot(e,t)>n}const o=new Map;export function registerBubble(e,t,n){return!e||!t||o.has(e)?!1:(o.set(e,{appId:t,expanded:!1,y:n,dragged:!1}),!0)}export function removeBubble(e){return o.delete(e)}export function hasBubble(e){return o.has(e)}export function setExpanded(e,t){const n=o.get(e);return!n||n.expanded===!!t?!1:(n.expanded=!!t,!0)}export function isExpanded(e){const t=o.get(e);return!!t&&t.expanded}export function expandedIds(){const e=new Set;return o.forEach((t,n)=>{t.expanded&&e.add(n)}),e}export function setBubbleY(e,t,n){const r=o.get(e);return r?(r.y=clampBubbleY(t,n),r.dragged=!0,!0):!1}export function bubbleY(e){const t=o.get(e);return t?t.y:null}export function isDragged(e){const t=o.get(e);return!!t&&t.dragged}export function bubbleCount(){return o.size}export function reconcilePositions(e,t=48,n=10,r=96){let u=0;o.forEach(B=>{B.dragged||(B.y=bubbleSlotY(u++,e,t,n,r))})}export function bubbleSnapshot(){const e=[];return o.forEach((t,n)=>e.push({id:n,appId:t.appId,expanded:t.expanded,y:t.y,dragged:t.dragged})),e}export function __resetBubbles(){o.clear()}export const DISMISS_ZONE_HEIGHT=96,DISMISS_ZONE_SIDE_RATIO=.6;export function inDismissZone(e,t,n,r,u=DISMISS_ZONE_HEIGHT,B=DISMISS_ZONE_SIDE_RATIO){if(t<r-u)return!1;const a=n*B/2;return Math.abs(e-n/2)<=a}export function fanOutRow(e,t,n=48,r=10){if(e<=0)return[];const u=n+r,B=e*n+(e-1)*r,a=Math.max(8,(t-B)/2);return Array.from({length:e},(c,s)=>a+s*u)}export function collapseOthers(e){let t=0;return o.forEach((n,r)=>{n.expanded&&r!==e&&(n.expanded=!1,t++)}),t}
